const lifespan:Record<DeviceCategory,number>={phone:7,laptop:7,desktop:8,component:7,tablet:7,monitor:8,tv:9,console:9,handheld:6,audio:6,camera:9,charger:7,cable:10,adapter:8,dock:7,storage:7,networking:7,'smart-home':6,wearable:5,peripheral:7,other:6}
const slug=(value:string)=>value.toLowerCase().replace(/\+/g,' plus ').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')
const easy=new Set<DeviceCategory>(['desktop','component','cable','adapter','peripheral'])

export const catalogExpansion:Device[]=rows.map(([brand,model,category,releaseYear,estimatedValueEur,ports,protocols,subcategory,highlights,maxInputWatts,maxOutputWatts,display])=>({
  id:`${slug(brand)}-${slug(model)}`,
  brand,model,category,subcategory,releaseYear,
  aliases:[model,`${brand} ${model}`],ports,protocols,maxInputWatts,maxOutputWatts,display,estimatedValueEur,
  estimatedLifespanYears:lifespan[category],
  repairability:easy.has(category)?'easy':['phone','tablet','monitor','tv','camera','wearable'].includes(category)?'professional':'moderate',
  source:`${brand} official specifications and WhatTech reference profile`,updatedAt:'2026-08-12',confidence:'medium',highlights,
}))
